export type compareAnalysesResponse200 = {
  data: AnalysisComparisonResponse;
  status: 200;
};

export type compareAnalysesResponseSuccess = compareAnalysesResponse200 & {
  headers: Headers;
};
export const getCompareAnalysesUrl = (
  caseId: string,
  params: CompareAnalysesParams
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : String(value));
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/1/cases/${caseId}/comparison?${stringifiedParams}`
    : `/api/1/cases/${caseId}/comparison`;
};

export const compareAnalyses = async (
  caseId: string,
  params: CompareAnalysesParams,
  options?: Parameters<typeof customFetch>[1]
): Promise<compareAnalysesResponseSuccess> => {
  return customFetch<compareAnalysesResponseSuccess>(
    getCompareAnalysesUrl(caseId, params),
    {
      ...options,
      method: "GET",
    }
  );
};

export const getCompareAnalysesQueryKey = (
  caseId: string,
  params?: CompareAnalysesParams
) => {
  return [
    `/api/1/cases/${caseId}/comparison`,
    ...(params ? [params] : []),
  ] as const;
};

export const getCompareAnalysesQueryOptions = <
  TData = Awaited<ReturnType<typeof compareAnalyses>>,
  TError = ErrorType<unknown>,
>(
  caseId: string,
  params: CompareAnalysesParams,
  options?: {
    query?: Partial<
      UseQueryOptions<
        Awaited<ReturnType<typeof compareAnalyses>>,
        TError,
        TData
      >
    >;
    request?: SecondParameter<typeof customFetch>;
  }
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getCompareAnalysesQueryKey(caseId, params);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof compareAnalyses>>> = ({
    signal,
  }) => compareAnalyses(caseId, params, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: caseId !== null && caseId !== undefined,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof compareAnalyses>>,
    TError,
    TData
  > & { queryKey: DataTag<QueryKey, TData, TError> };
};

